c = int(input())
store = {}
gets = []
for _ in range(c):
    parts = input().split()
    cmd = parts[0]
    if cmd == "SET":
        store[parts[1]] = parts[2]
    elif cmd == "GET":
        if parts[1] in store:
            gets.append(store[parts[1]])
        else:
            gets.append("NULL")
    elif cmd == "DEL":
        if parts[1] in store:
            del store[parts[1]]
with open("/tmp/atom_store.txt", "w") as f:
    for key in store:
        f.write(key + " " + store[key] + "\n")
disk = {}
with open("/tmp/atom_store.txt", "r") as f:
    for line in f:
        tokens = line.rstrip("\n").split(" ", 1)
        disk[tokens[0]] = tokens[1]
for g in gets:
    print(g)
for key in sorted(disk.keys()):
    print(key + "=" + disk[key])

n = int(input())
rows = []
for _ in range(n):
    rows.append(input())
with open("/tmp/atom_grades.txt", "w") as f:
    for row in rows:
        f.write(row + "\n")

total = 0
valid = 0
bad_lines = []
line_no = 0
with open("/tmp/atom_grades.txt", "r") as f:
    for line in f:
        line_no += 1
        clean = line.rstrip("\n")
        parts = clean.split()
        ok = False
        try:
            if len(parts) == 2:
                score = int(parts[1])
                if 0 <= score <= 100:
                    ok = True
        except ValueError:
            ok = False
        if ok:
            total += score
            valid += 1
        else:
            bad_lines.append(line_no)

if valid > 0:
    print(f"avg={total / valid:.2f}")
else:
    print("avg=NA")
print("bad=" + str(len(bad_lines)))
if bad_lines:
    print("lines=" + " ".join(str(x) for x in bad_lines))
else:
    print("lines=none")
